package xyz.jovanstoiljkovic.isa.dtos.song;import xyz.jovanstoiljkovic.isa.dtos.BaseDTO;import xyz.jovanstoiljkovic.isa.dtos.artist.ArtistDTOLeaf;import xyz.jovanstoiljkovic.isa.models.Song;public class SongDTO extends BaseDTO<Song> {    private Long id;    private String name;    private String url;    private ArtistDTOLeaf artist;    public SongDTO() {    }    public SongDTO(Long id, String name, String url, ArtistDTOLeaf artist) {        this.id = id;        this.name = name;        this.url = url;        this.artist = artist;    }    public Long getId() {        return id;    }    public void setId(Long id) {        this.id = id;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public String getUrl() {        return url;    }    public void setUrl(String url) {        this.url = url;    }    public ArtistDTOLeaf getArtist() {        return artist;    }    public void setArtist(ArtistDTOLeaf artist) {        this.artist = artist;    }}